<script>
const fm=document.getElementById('featuresModal');fm?.addEventListener('show.bs.modal',e=>{const b=e.relatedTarget,f=fm.querySelector('form'),d=JSON.parse(b.dataset.features||'{}');f.querySelector('[name=id]').value=b.dataset.id;document.getElementById('feature-station-name').textContent=b.dataset.name;f.querySelectorAll('[data-feature]').forEach(s=>{const v=d[s.dataset.feature]?.value;s.value=v===true?'on':v===false?'off':'inherit'});f.querySelector('[name=trial_minutes]').value=d.trial?.config?.minutes||10;f.querySelector('[name=convert_points]').value=d.points_convert?.config?.points||10;f.querySelector('[name=convert_minutes]').value=d.points_convert?.config?.minutes||5;});
