const lm=document.getElementById('linkVendoModal');lm?.addEventListener('show.bs.modal',e=>{const b=e.relatedTarget,f=lm.querySelector('form');f.querySelector('[name=station_id]').value=b.dataset.stationId;f.querySelector('[name=device_id]').value=b.dataset.deviceId||'';document.getElementById('link-vendo-station').textContent=b.dataset.stationName;});
